// دریافت خروجی Basic LLM Chain
let data = $json;

// در بعضی نسخه‌ها خروجی داخل output قرار دارد
if (data.output !== undefined) {
  data = data.output;
}

// اگر خروجی به‌صورت رشته باشد، Markdown احتمالی را حذف کن
if (typeof data === 'string') {
  let jsonText = data.trim();

  jsonText = jsonText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    data = JSON.parse(jsonText);
  } catch (error) {
    throw new Error(
      `LLM output is not valid JSON: ${error.message}`
    );
  }
}

// کنترل ساختار اصلی
if (!data || typeof data !== 'object' || Array.isArray(data)) {
  throw new Error('Storyboard output is empty or invalid.');
}

if (!Array.isArray(data.scenes)) {
  throw new Error('The "scenes" field must be an array.');
}

// باید دقیقاً سه صحنه وجود داشته باشد
if (data.scenes.length !== 3) {
  throw new Error(
    `Exactly 3 scenes are required, but received ${data.scenes.length}.`
  );
}

/**
 * پاک‌سازی عمومی متن فارسی
 * مناسب voice و subtitle
 */
function normalizePersianText(value) {
  return String(value || '')
    // یکسان‌سازی حروف عربی و فارسی
    .replace(/ي/g, 'ی')
    .replace(/ى/g, 'ی')
    .replace(/ك/g, 'ک')

    // تبدیل ویرگول و علامت سؤال انگلیسی
    .replace(/,/g, '،')
    .replace(/\?/g, '؟')

    // حذف فاصله پیش از علائم نگارشی
    .replace(/\s+([،؛:.!؟])/g, '$1')

    // افزودن یک فاصله پس از علائم، در صورت نیاز
    .replace(/([،؛.!؟])(?=[^\s\d])/g, '$1 ')

    // جلوگیری از فاصله‌گذاری داخل اعداد اعشاری
    .replace(/(\d)\.\s+(\d)/g, '$1.$2')

    // حذف نشانه‌های تکراری
    .replace(/،{2,}/g, '،')
    .replace(/؛{2,}/g, '؛')
    .replace(/\.{2,}/g, '.')
    .replace(/؟{2,}/g, '؟')
    .replace(/!{2,}/g, '!')

    // تبدیل چند فاصله به یک فاصله
    .replace(/[ \t]+/g, ' ')

    // حذف فاصله‌های ابتدا و انتها
    .trim();
}

/**
 * پاک‌سازی ویژه‌ی متن گوینده
 * این تابع فقط نشانه‌گذاری را اصلاح می‌کند؛
 * بازنویسی دستوری باید توسط LLM انجام شود.
 */
function normalizeVoiceText(value) {
  let text = normalizePersianText(value);

  // نام پلتفرم X برای خواندن طبیعی‌تر
  text = text.replace(
    /(^|[\s،؛])X(?=$|[\s،؛.!؟])/g,
    '$1ایکس'
  );

  // برخی مخفف‌های متداول برای TTS
  const voiceReplacements = [
    [/\bAfD\b/gi, 'آ اِف دِ'],
    [/\bCDU\b/g, 'سِ دِ او'],
    [/\bCSU\b/g, 'سِ اِس او'],
    [/\bSPD\b/g, 'اِس پِ دِ'],
    [/\bFDP\b/g, 'اِف دِ پِ'],
    [/\bEU\b/g, 'اتحادیه اروپا'],
    [/\bNATO\b/gi, 'ناتو'],
  ];

  for (const [pattern, replacement] of voiceReplacements) {
    text = text.replace(pattern, replacement);
  }

  return text.trim();
}

/**
 * کنترل پایان طبیعی جمله
 */
function ensureSentenceEnding(value) {
  const text = String(value || '').trim();

  if (!text) {
    return text;
  }

  if (/[.!؟]$/.test(text)) {
    return text;
  }

  return `${text}.`;
}

// اعتبارسنجی و پاک‌سازی هر صحنه
const normalizedScenes = data.scenes.map((scene, index) => ({
  scene_number: index + 1,
  duration: 20,
  voice: scene.voice.trim(),
  subtitle: scene.subtitle.trim(),
  image_prompt: scene.image_prompt.trim(),
}));

// محاسبه مجموع زمان صحنه‌ها
const calculatedDuration = normalizedScenes.reduce(
  (sum, scene) => sum + scene.duration,
  0
);

if (calculatedDuration !== 60) {
  throw new Error(
    `Scene durations must total 60 seconds, but total is ${calculatedDuration}.`
  );
}

// کنترل duration اصلی
if (Number(data.duration) !== 60) {
  throw new Error(
    `Top-level duration must be 60, but received ${data.duration}.`
  );
}

return [
  {
    json: {
      title: normalizePersianText(data.title),
      duration: 60,
      scene_count: normalizedScenes.length,
      calculated_duration: calculatedDuration,
      validation_status: 'valid',
      scenes: normalizedScenes,
    },
  },
];

