const history = $json.history ?? {};
const promptId = $json.prompt_id;

if (!promptId) {
  throw new Error('ComfyUI prompt_id is missing.');
}

const job = history[promptId];

if (!job) {
  throw new Error(
    `No ComfyUI history entry found for prompt ID: ${promptId}`
  );
}

if (job?.status?.completed !== true) {
  throw new Error(
    `ComfyUI job is not completed. Status: ${
      job?.status?.status_str ?? 'unknown'
    }`
  );
}

let image = null;
let outputNodeId = null;

for (const [nodeId, output] of Object.entries(job.outputs ?? {})) {
  if (Array.isArray(output.images) && output.images.length > 0) {
    image = output.images[0];
    outputNodeId = nodeId;
    break;
  }
}

if (!image) {
  throw new Error('No generated image found in ComfyUI outputs.');
}

const baseUrl = 'http://127.0.0.1:8188';

const filename = image.filename;
const subfolder = image.subfolder ?? '';
const fileType = image.type ?? 'output';

return [
  {
    json: {
      prompt_id: promptId,
      output_node_id: outputNodeId,
      filename,
      subfolder,
      file_type: fileType,
      poll_attempt: $json.poll_attempt,
      image_url:
        `${baseUrl}/view` +
        `?filename=${encodeURIComponent(filename)}` +
        `&subfolder=${encodeURIComponent(subfolder)}` +
        `&type=${encodeURIComponent(fileType)}`,
    },
  },
];

const fs = require('fs');

const source = $('PrepareImagePrompt').item.json;

const executionId = String($execution.id);
const executionFolder =
  `C:\\News2Video-AI\\temp\\execution_${executionId}`;

const sceneNumber = Number(source.scene_number);

if (!sceneNumber) {
  throw new Error('scene_number is missing.');
}

// ساخت پوشه، اگر هنوز وجود ندارد
fs.mkdirSync(executionFolder, {
  recursive: true,
});

return [
  {
    json: {
      scene_number: sceneNumber,
      duration: source.duration,
      voice: source.voice,
      subtitle: source.subtitle,
      final_image_prompt: source.final_image_prompt,

      execution_id: executionId,
      execution_folder: executionFolder,

      image_path:
        `${executionFolder}\\scene_${sceneNumber}.png`,

      audio_path:
        `${executionFolder}\\scene_${sceneNumber}_voice.mp3`,

      video_path:
        `${executionFolder}\\scene_${sceneNumber}.mp4`,

      prompt_id:
        $('ExtractComfyUIImage').item.json.prompt_id,

      filename:
        $('ExtractComfyUIImage').item.json.filename,
    },

    // نگه‌داشتن فایل تصویر دانلودشده
    binary: $binary,
  },
];

const history = $json ?? {};

const promptId =
  $('GenerateImageWithComfyUI').item.json.prompt_id;

if (!promptId) {
  throw new Error('ComfyUI prompt_id is missing.');
}

// دریافت تلاش قبلی از چرخه Polling
let previousAttempt = 0;

try {
  previousAttempt =
    Number($('CheckComfyUIStatus').item.json.poll_attempt) || 0;
} catch (error) {
  previousAttempt = 0;
}

const pollAttempt = previousAttempt + 1;

// دقیقاً Job مربوط به همین prompt را بررسی می‌کنیم
const job = history[promptId];

// History هنوز آماده نیست
if (!job) {
  return [
    {
      json: {
        completed: false,
        failed: false,
        status: 'waiting',
        poll_attempt: pollAttempt,
        prompt_id: promptId,
        history,
      },
    },
  ];
}

const status =
  job?.status?.status_str ?? 'unknown';

const completed =
  job?.status?.completed === true;

const failed =
  status === 'error' ||
  status === 'failed';

// جزئیات خطای احتمالی ComfyUI
const messages =
  Array.isArray(job?.status?.messages)
    ? job.status.messages
    : [];

return [
  {
    json: {
      completed,
      failed,
      status,
      poll_attempt: pollAttempt,
      prompt_id: promptId,
      history,
      status_messages: messages,
    },
  },
];

throw new Error(
  `ComfyUI did not complete the image after ${$json.poll_attempt} checks. ` +
  `Prompt ID: ${$json.prompt_id}, last status: ${$json.status}`
);

const sceneNumber = Number($json.scene_number);
const voiceText = String($json.voice || '').trim();

if (!sceneNumber) {
  throw new Error('scene_number is missing.');
}

if (!voiceText) {
  throw new Error(`Scene ${sceneNumber}: voice text is empty.`);
}

const pythonPath =
  'C:\\Users\\USERNAME\\AppData\\Local\\Comfy-Desktop\\' +
  'ComfyUI-Installs\\Comfy UI\\ComfyUI\\.venv\\Scripts\\python.exe';

const scriptPath =
  'C:\\News2Video-AI\\scripts\\tts.py';

const audioPath = $json.audio_path;

if (!audioPath) {
  throw new Error(`Scene ${sceneNumber}: audio_path is missing.`);
}

const textBase64 = Buffer
  .from(voiceText, 'utf8')
  .toString('base64');

const command =
  `powershell.exe -NoProfile -ExecutionPolicy Bypass -Command ` +
  `"& '${pythonPath}' ` +
  `'${scriptPath}' ` +
  `--text-base64 '${textBase64}' ` +
  `--output '${audioPath}' ` +
  `--voice 'fa-IR-FaridNeural' ` +
  `--rate=-5% ` +
  `--pitch=-2Hz"`;  

return [
  {
    json: {
      ...$json,
      text_base64: textBase64,
      tts_command: command,
    },
    binary: $binary,
  },
];

const fs = require('fs');

const source = $('PrepareTTSCommand').item.json;

const sceneNumber = Number(source.scene_number);
const subtitle = String(source.subtitle || '').trim();

const pythonPath =
  'C:\\Users\\USERNAME\\AppData\\Local\\Comfy-Desktop\\' +
  'ComfyUI-Installs\\Comfy UI\\ComfyUI\\.venv\\Scripts\\python.exe';

const scriptPath =
  'C:\\News2Video-AI\\scripts\\video_engine.py';

const imagePath = source.image_path;
const audioPath = source.audio_path;
const videoPath = source.video_path;

// Debug
if (!fs.existsSync(pythonPath)) {
  throw new Error(`Python not found: ${pythonPath}`);
}

if (!fs.existsSync(scriptPath)) {
  throw new Error(`video_engine.py not found: ${scriptPath}`);
