  `"${scriptPath}" ` +
  `render-scene ` +
  `--image "${imagePath}" ` +
  `--audio "${audioPath}" ` +
  `--output "${videoPath}" ` +
  `--subtitle-base64 "${subtitleBase64}" ` +
  `--width 1080 ` +
  `--height 1920 ` +
  `--fps 30`;

return [
