      subtitle_base64: subtitleBase64,
      render_command: command,

      debug: {
        python_exists: fs.existsSync(pythonPath),
        script_exists: fs.existsSync(scriptPath),
        image_exists: fs.existsSync(imagePath),
        audio_exists: fs.existsSync(audioPath),
        image_path: imagePath,
        audio_path: audioPath,
        video_path: videoPath,
      },
    },
  },
];

const source = $('PrepareRenderSceneCommand').item.json;

if ($json.exitCode !== 0) {
  throw new Error(
    `FFmpeg render failed for scene ${source.scene_number}.\n` +
    `stderr: ${$json.stderr || 'no stderr'}`
  );
}

return [
  {
    json: {
      ...source,
      render_exit_code: $json.exitCode,
      render_stdout: $json.stdout,
      render_stderr: $json.stderr,
      render_status: 'success',
    },
  },
];

const fs = require("fs");

const executionFolder =
`C:\\News2Video-AI\\temp\\execution_${$execution.id}`;

const listFile =
`${executionFolder}\\concat.txt`;

const finalVideo =
`${executionFolder}\\final_video.mp4`;

const content = [
"file 'scene_1.mp4'",
"file 'scene_2.mp4'",
"file 'scene_3.mp4'"
].join("\r\n");

fs.writeFileSync(
listFile,
content,
"utf8"
);

const command =
`"C:\\ffmpeg\\bin\\ffmpeg.exe" -y -f concat -safe 0 ` +
`-i "${listFile}" ` +
`-c copy ` +
`"${finalVideo}"`;

return [{
json:{
execution_folder:executionFolder,
concat_file:listFile,
final_video:finalVideo,
merge_command:command
}
}];

const fs = require('fs');

// خروجی Execute Command
const mergeResult = $json;

// مسیر فایل از Node قبلی گرفته می‌شود
const source = $('BuildConcatCommand').first().json;

const finalVideo = source.final_video;

if (mergeResult.exitCode !== 0) {
  throw new Error(
    `FFmpeg merge failed.\n` +
    `Exit code: ${mergeResult.exitCode}\n` +
    `stderr: ${mergeResult.stderr || 'No stderr output'}`
  );
}

if (
  typeof finalVideo !== 'string' ||
  finalVideo.trim() === ''
) {
  throw new Error(
    'final_video path is missing in BuildConcatCommand.'
  );
}

if (!fs.existsSync(finalVideo)) {
  throw new Error(
    `Final video was not created:\n${finalVideo}`
  );
}

const size = fs.statSync(finalVideo).size;

if (size < 100000) {
  throw new Error(
    `Final video looks invalid. File size: ${size} bytes`
  );
}

return [
  {
    json: {
      status: 'success',

      execution_id: source.execution_id,
      execution_folder: source.execution_folder,

      final_video: finalVideo,

      size_bytes: size,
      size_mb: Number(
        (size / 1024 / 1024).toFixed(2)
      ),

      merge_exit_code: mergeResult.exitCode,
      merge_stdout: mergeResult.stdout,
      merge_stderr: mergeResult.stderr,
    },
  },
];

const fs = require('fs');
const path = require('path');

const source = $('ValidateCompleteVideo').first().json;

const executionFolder = source.execution_folder;
const finalVideo = source.final_video;

if (!executionFolder) {
  throw new Error('execution_folder is missing.');
}

if (!fs.existsSync(executionFolder)) {
  return [
    {
      json: {
        cleanup_status: 'skipped',
        reason: 'Execution folder does not exist.',
        execution_folder: executionFolder,
      },
    },
  ];
}

// فعلاً فایل نهایی را نگه می‌داریم
const keepFiles = new Set([
  path.basename(finalVideo),
]);

const deletedFiles = [];
const keptFiles = [];

for (const entry of fs.readdirSync(executionFolder)) {
  const fullPath = path.join(executionFolder, entry);

  if (keepFiles.has(entry)) {
    keptFiles.push(fullPath);
    continue;
  }

  const stats = fs.statSync(fullPath);

  if (stats.isFile()) {
    fs.unlinkSync(fullPath);
    deletedFiles.push(fullPath);
  }
}

return [
  {
    json: {
      cleanup_status: 'success',
      execution_folder: executionFolder,
      deleted_count: deletedFiles.length,
      deleted_files: deletedFiles,
      kept_files: keptFiles,
    },
  },
];

const fs = require('fs');
const path = require('path');

const source = $('ValidateFinalVideo').first().json;

const inputVideo = source.final_video;

const musicPath =
  'C:\\News2Video-AI\\assets\\background_music.mp3';

const outputVideo = path.join(
  source.execution_folder,
  'final_video_music.mp4'
);

if (!fs.existsSync(inputVideo)) {
  throw new Error(`Input video not found: ${inputVideo}`);
}

if (!fs.existsSync(musicPath)) {
  throw new Error(`Background music not found: ${musicPath}`);
}

const command =
  `"C:\\ffmpeg\\bin\\ffmpeg.exe" -y ` +
  `-i "${inputVideo}" ` +
  `-stream_loop -1 -i "${musicPath}" ` +
  `-filter_complex "` +
  `[1:a]volume=0.08[music];` +
  `[0:a][music]amix=inputs=2:duration=first:dropout_transition=2[aout]` +
  `" ` +
  `-map 0:v:0 ` +
  `-map "[aout]" ` +
  `-c:v copy ` +
  `-c:a aac ` +
  `-b:a 192k ` +
  `-shortest ` +
  `-movflags +faststart ` +
  `"${outputVideo}"`;

return [
  {
    json: {
      ...source,
      background_music: musicPath,
      final_video_without_music: inputVideo,
      final_video: outputVideo,
      music_command: command,
    },
  },
];

const fs = require('fs');

