  'C:\\News2Video-AI\\assets\\intro.mp4';

const outroVideo =
  'C:\\News2Video-AI\\assets\\outro.mp4';

const outputVideo = path.join(
  source.execution_folder,
  'final_video_complete.mp4'
);

if (!fs.existsSync(mainVideo)) {
  throw new Error(
    `Main video not found: ${mainVideo}`
  );
}

if (!fs.existsSync(introVideo)) {
  throw new Error(
    `Intro video not found: ${introVideo}`
  );
}

if (!fs.existsSync(outroVideo)) {
  throw new Error(
    `Outro video not found: ${outroVideo}`
  );
