const command =
  `"C:\\ffmpeg\\bin\\ffmpeg.exe" -y ` +
  `-i "${introVideo}" ` +
  `-i "${mainVideo}" ` +
  `-i "${outroVideo}" ` +
  `-filter_complex "` +

  `[0:v]scale=1080:1920,fps=30,setsar=1[v0];` +
  `[1:v]scale=1080:1920,fps=30,setsar=1[v1];` +
  `[2:v]scale=1080:1920,fps=30,setsar=1[v2];` +

  `[0:a]aresample=48000[a0];` +
  `[1:a]aresample=48000[a1];` +
  `[2:a]aresample=48000[a2];` +

  `[v0][a0][v1][a1][v2][a2]` +
  `concat=n=3:v=1:a=1[vout][aout]` +

  `" ` +
  `-map "[vout]" ` +
  `-map "[aout]" ` +
  `-c:v libx264 ` +
  `-preset medium ` +
  `-crf 20 ` +
  `-c:a aac ` +
  `-b:a 192k ` +
  `-movflags +faststart ` +
  `"${outputVideo}"`;

return [
  {
    json: {
      ...source,

      intro_video: introVideo,
      outro_video: outroVideo,

      final_video_before_intro_outro: mainVideo,
      final_video: outputVideo,

      intro_outro_command: command,
    },
  },
];

const fs = require('fs');

const source =
  $('BuildIntroOutroCommand').first().json;

if ($json.exitCode !== 0) {
  throw new Error(
    `FFmpeg Intro/Outro failed.\n` +
    `Exit code: ${$json.exitCode}\n` +
    `stderr: ${$json.stderr || 'No stderr'}`
  );
}

const finalVideo = source.final_video;

if (
  typeof finalVideo !== 'string' ||
  finalVideo.trim() === ''
) {
  throw new Error(
    'Final complete video path is missing.'
  );
}

if (!fs.existsSync(finalVideo)) {
  throw new Error(
    `Complete video was not created:\n${finalVideo}`
  );
}

const size = fs.statSync(finalVideo).size;

if (size < 100000) {
  throw new Error(
    `Complete video looks invalid: ${size} bytes`
  );
}

return [
  {
    json: {
      ...source,

      status: 'success',

      final_video: finalVideo,

      final_video_size_bytes: size,
      final_video_size_mb:
        Number((size / 1024 / 1024).toFixed(2)),

      intro_outro_exit_code: $json.exitCode,
      intro_outro_stderr: $json.stderr,
    },
  },
];

const input = $json.body ?? $json;

const titleFa =
  String(input.title_fa || '').trim();

const shortSummaryFa =
  String(input.short_summary_fa || '').trim();

const teaserFa =
  String(input.teaser_fa || '').trim();

const link =
  String(input.link || '').trim();

const source =
  String(
    input.source_name ||
    input.sourceFeed ||
    input.sourceHost ||
    ''
  ).trim();

const importance =
  Number(input.importance || 0);

if (!titleFa) {
  throw new Error('title_fa is missing');
}

if (!teaserFa && !shortSummaryFa) {
  throw new Error('No Persian news content received');
}

return [
  {
    json: {
      title_fa: titleFa,
      short_summary_fa: shortSummaryFa,
      teaser_fa: teaserFa,
      link,
      source,
      importance,

      video_news_text: [
        `عنوان: ${titleFa}`,
        shortSummaryFa
          ? `خلاصه: ${shortSummaryFa}`
          : '',
        teaserFa
          ? `متن خبر: ${teaserFa}`
          : '',
        source
          ? `منبع: ${source}`
          : '',
      ]
        .filter(Boolean)
        .join('\n\n')
    }
  }
];

const content = $json.message?.content;

if (!content || typeof content !== 'string') {
  throw new Error(
    'Ollama response does not contain message.content.'
  );
}

let storyboard;

try {
  storyboard = JSON.parse(content);
} catch (error) {
  throw new Error(
    `Ollama returned invalid JSON: ${error.message}\n\n` +
    `Raw content:\n${content}`
  );
}

if (
  !storyboard ||
  typeof storyboard !== 'object' ||
  Array.isArray(storyboard)
) {
  throw new Error(
    'Parsed Ollama storyboard is not a valid object.'
  );
}

return [
  {
    json: storyboard,
  },
];
